<template>
  <section class="operation-block" aria-labelledby="kitchen-time-title">
    <header><div><p class="module-eyebrow">THỜI GIAN BẾP</p><h3 id="kitchen-time-title">Từ xác nhận đến hoàn tất</h3><p>Chỉ dùng ConfirmedAt và ReadyAt hợp lệ; không gọi là thời gian phục vụ khách.</p></div><button type="button" aria-label="Làm mới thời gian bếp" title="Làm mới" :disabled="loading" @click="load">↻</button></header>
    <div v-if="error" class="block-error" role="alert">{{ error }} <button type="button" aria-label="Thử tải lại thời gian bếp" @click="load">Thử lại</button></div><div v-else-if="loading" class="block-loading" role="status">Đang tải…</div>
    <template v-else-if="data"><div class="mini-kpis"><span><b>{{ data.summary.servedQuantity }}</b> suất</span><span><b>{{ data.summary.validSampleCount }}</b> mẫu hợp lệ</span><span><b>{{ data.summary.missingSampleCount }}</b> thiếu mốc</span></div><div class="table-scroll"><table><thead><tr><th>Món / biến thể</th><th>Suất</th><th>Mẫu hợp lệ</th><th>Thiếu mốc</th><th>Trung bình</th></tr></thead><tbody><tr v-for="row in data.rows" :key="`${row.foodName}-${row.variantName}`"><td><strong>{{ row.foodName }}</strong><small>{{ row.variantName }}</small></td><td>{{ row.servedQuantity }}</td><td>{{ row.validSampleCount }}</td><td>{{ row.missingOrInvalidSampleCount }}</td><td>{{ row.averageMinutes == null ? 'Chưa tính' : `${row.averageMinutes} phút` }}</td></tr></tbody></table></div></template>
  </section>
</template>
<script setup>
import { ref, watch } from 'vue';import axios from 'axios'
const API_BASE=import.meta.env.VITE_API_URL||'http://localhost:5079'
const props=defineProps({fromDate:{type:String,required:true},toDate:{type:String,required:true}});const loading=ref(false);const error=ref('');const data=ref(null);let requestSequence=0
async function load(){const requestId=++requestSequence;loading.value=true;error.value='';try{const response=await axios.get(`${API_BASE}/api/admin/reports/operations/kitchen-time`,{params:{fromDate:props.fromDate,toDate:props.toDate},timeout:5000});if(requestId!==requestSequence)return;data.value=response.data?.data||null;if(!data.value)throw new Error('Dữ liệu thời gian bếp không hợp lệ.')}catch(e){if(requestId===requestSequence)error.value=e.response?.data?.message||e.message||'Chưa tải được thời gian bếp.'}finally{if(requestId===requestSequence)loading.value=false}}watch(()=>[props.fromDate,props.toDate],load,{immediate:true})
</script>
<style scoped>
.operation-block{display:flex;flex-direction:column;gap:12px;padding:16px;background:#fff;border:1px solid #dfe5ef;border-radius:10px;color:#172033}.operation-block header{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.operation-block header button{width:40px;height:40px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#0f766e;font-size:1.1rem;cursor:pointer}.module-eyebrow{margin:0 0 4px;color:#0f766e;font-size:.68rem;font-weight:800;letter-spacing:.1em}.operation-block h3{margin:0;font-size:1rem}.operation-block p:not(.module-eyebrow){margin:4px 0 0;color:#64748b;font-size:.78rem}.mini-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.mini-kpis span{padding:10px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:7px;color:#64748b;font-size:.72rem}.mini-kpis b{display:block;color:#172033;font-size:1rem}.table-scroll{overflow-x:auto;border:1px solid #e2e8f0;border-radius:7px}.operation-block table{width:100%;min-width:600px;border-collapse:collapse;font-size:.75rem}.operation-block th,.operation-block td{padding:8px;border-bottom:1px solid #edf0f5;text-align:left;white-space:nowrap}.operation-block th{background:#f8fafc;color:#64748b;font-size:.67rem;text-transform:uppercase}.operation-block tr:last-child td{border:0}.operation-block small{display:block;color:#94a3b8;margin-top:2px}.block-error{padding:10px;color:#991b1b;background:#fef2f2;border:1px solid #fecaca;border-radius:7px;font-size:.78rem}.block-error button{margin-left:5px;border:0;background:transparent;color:#991b1b;text-decoration:underline;cursor:pointer}.block-loading{min-height:110px;display:grid;place-items:center;color:#64748b;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:7px;font-size:.8rem}@media(max-width:600px){.mini-kpis{grid-template-columns:1fr}.mini-kpis span{display:flex;justify-content:space-between;align-items:center}.mini-kpis b{display:inline}}
</style>
